class Solution:
    def hasSpecialSubstring(self, s: str, k: int) -> bool:
        n = len(s)
        # Iterate through all substrings of length k
        for i in range(n - k + 1):
            substring = s[i : i + k]

            # Condition 1: Substring consists of only one distinct character
            if len(set(substring)) != 1:
                continue

            char_in_sub = substring[0]

            # Condition 2: If there is a character immediately before, it must be different
            if i > 0:
                if s[i - 1] == char_in_sub:
                    continue

            # Condition 3: If there is a character immediately after, it must be different
            if i + k < n:
                if s[i + k] == char_in_sub:
                    continue

            # If all conditions are met
            return True

        return False
