class Solution:
    def findValidPair(self, s: str) -> str:
        # Count the frequency of each digit in the string
        counts = {}
        for char in s:
            counts[char] = counts.get(char, 0) + 1

        # Iterate through the string to find adjacent pairs
        for i in range(len(s) - 1):
            d1 = s[i]
            d2 = s[i+1]

            # Condition 1: The first digit is not equal to the second
            if d1 == d2:
                continue

            # Condition 2: Each digit appears exactly as many times as its numeric value
            # Convert characters to integers
            val1 = int(d1)
            val2 = int(d2)

            if counts[d1] == val1 and counts[d2] == val2:
                return d1 + d2

        # If no valid pair is found
        return ""
